import {esc,icon} from './utils.js';
let current=null;
export function closeDialog(value=null){current?.(value)}
function modal(title,body,setup){closeDialog();const previous=document.activeElement;const dialog=document.createElement('dialog');dialog.className='app-dialog';dialog.innerHTML=`<div class="sheet-handle"></div><header><div><small>CODEQUEST</small><h2>${esc(title)}</h2></div><button class="icon-btn" data-close aria-label="Close dialog">${icon('close')}</button></header>${body}`;document.body.append(dialog);return new Promise(resolve=>{current=value=>{current=null;dialog.close();dialog.remove();previous?.focus();resolve(value)};dialog.addEventListener('cancel',e=>{e.preventDefault();closeDialog()});dialog.querySelector('[data-close]').onclick=()=>closeDialog();dialog.addEventListener('click',e=>{if(e.target===dialog)closeDialog()});setup(dialog);dialog.showModal()})}
export function askConfirm(message){return modal('Before you continue',`<p class="dialog-copy">${esc(message)}</p><div class="dialog-actions"><button class="btn" data-cancel>Keep current data</button><button class="btn primary" data-confirm>Continue</button></div>`,d=>{d.querySelector('[data-cancel]').onclick=()=>closeDialog(false);d.querySelector('[data-confirm]').onclick=()=>closeDialog(true)}).then(Boolean)}
export function enhanceSelects(root=document){for(const select of root.querySelectorAll('select:not([data-enhanced])')){select.dataset.enhanced='1';const trigger=document.createElement('button');trigger.type='button';trigger.className='select-trigger';trigger.setAttribute('aria-haspopup','dialog');const label=select.closest('label')?.childNodes[0]?.textContent?.trim()||select.getAttribute('aria-label')||'Choose an option';trigger.setAttribute('aria-label',label);const sync=()=>{trigger.innerHTML=`<span>${esc(select.selectedOptions[0]?.textContent||'Select')}</span>${icon('back')}`};sync();select.hidden=true;select.after(trigger);select.addEventListener('change',sync);trigger.onclick=async()=>{trigger.setAttribute('aria-expanded','true');const options=Array.from(select.options);const value=await modal(label,`<label class="picker-search">${icon('search')}<input type="search" placeholder="Find ${esc(label.toLowerCase())}…" aria-label="Search options"></label><div class="picker-list">${options.map((o,i)=>`<button type="button" class="picker-option ${o.selected?'chosen':''}" data-index="${i}" ${o.disabled?'disabled':''}><span class="picker-initial">${esc(o.textContent.slice(0,2))}</span><span>${esc(o.textContent)}</span>${o.selected?icon('check'):''}</button>`).join('')}</div>`,d=>{d.querySelector('input').oninput=e=>{const term=e.target.value.toLowerCase();d.querySelectorAll('[data-index]').forEach(b=>b.hidden=!options[Number(b.dataset.index)].textContent.toLowerCase().includes(term))};d.querySelectorAll('[data-index]').forEach(b=>b.onclick=()=>closeDialog(options[Number(b.dataset.index)].value))});trigger.setAttribute('aria-expanded','false');if(value!==null){select.value=value;select.dispatchEvent(new Event('change',{bubbles:true}))}}}}
